-- OA 微服务拆分：新增 5 个服务配置 + 网关路由拆分（2026-08-20）
-- 说明：在执行 sql/ry_config_oa_20260819.sql 之后执行本脚本（幂等）。
--       网关含 OA 审批/待办/日程/通讯录/聚合服务路由 + /oa/** 兜底；ERP 路由为共享 Nacos 现状，保留。
-- 注意：运行时通过 Nacos 控制台/API 发布；本脚本供全新环境初始化使用。
USE ry-config;

UPDATE config_info SET content = 'spring:\n  data:\n    redis:\n      host: localhost\n      port: 6379\n      password: \n  cloud:\n    gateway:\n      server:\n        webflux:\n          discovery:\n            locator:\n              lowerCaseServiceId: true\n              enabled: true\n          routes:\n            # 认证中心\n            - id: ruoyi-auth\n              uri: lb://ruoyi-auth\n              predicates:\n                - Path=/auth/**\n              filters:\n                # 验证码处理\n                - name: CacheRequestBody\n                  args:\n                    bodyClass: java.lang.String\n                - ValidateCodeFilter\n                - StripPrefix=1\n            # 代码生成\n            - id: ruoyi-gen\n              uri: lb://ruoyi-gen\n              predicates:\n                - Path=/code/**\n              filters:\n                - StripPrefix=1\n            # 定时任务\n            - id: ruoyi-job\n              uri: lb://ruoyi-job\n              predicates:\n                - Path=/schedule/**\n              filters:\n                - StripPrefix=1\n            # ERP 基础资料\n            - id: ruoyi-erp-base\n              uri: lb://ruoyi-erp-base\n              predicates:\n                - Path=/erp/material/**,/erp/supplier/**,/erp/customer/**,/erp/warehouse/**\n              filters:\n                - StripPrefix=1\n            # ERP 采购\n            - id: ruoyi-erp-purchase\n              uri: lb://ruoyi-erp-purchase\n              predicates:\n                - Path=/erp/purchase/**\n              filters:\n                - StripPrefix=1\n            # ERP 销售\n            - id: ruoyi-erp-sale\n              uri: lb://ruoyi-erp-sale\n              predicates:\n                - Path=/erp/sale/**\n              filters:\n                - StripPrefix=1\n            # ERP 库存\n            - id: ruoyi-erp-stock\n              uri: lb://ruoyi-erp-stock\n              predicates:\n                - Path=/erp/stock/**\n              filters:\n                - StripPrefix=1\n            # ERP 财务\n            - id: ruoyi-erp-finance\n              uri: lb://ruoyi-erp-finance\n              predicates:\n                - Path=/erp/finance/**\n              filters:\n                - StripPrefix=1\n            # ERP 生产\n            - id: ruoyi-erp-production\n              uri: lb://ruoyi-erp-production\n              predicates:\n                - Path=/erp/production/**\n              filters:\n                - StripPrefix=1\n            # ERP 报表 + 工作台待办\n            - id: ruoyi-erp-report\n              uri: lb://ruoyi-erp-report\n              predicates:\n                - Path=/erp/report/**,/erp/order/**\n              filters:\n                - StripPrefix=1            # OA 审批服务\n            - id: ruoyi-approval\n              uri: lb://ruoyi-approval\n              predicates:\n                - Path=/oa/approval/**\n              filters:\n                - StripPrefix=1\n            # OA 待办服务\n            - id: ruoyi-todo\n              uri: lb://ruoyi-todo\n              predicates:\n                - Path=/oa/todo/**\n              filters:\n                - StripPrefix=1\n            # OA 日程服务\n            - id: ruoyi-calendar\n              uri: lb://ruoyi-calendar\n              predicates:\n                - Path=/oa/calendar/**\n              filters:\n                - StripPrefix=1\n            # OA 通讯录服务\n            - id: ruoyi-contacts\n              uri: lb://ruoyi-contacts\n              predicates:\n                - Path=/oa/contacts/**\n              filters:\n                - StripPrefix=1\n            # OA 工作台聚合服务\n            - id: ruoyi-portal\n              uri: lb://ruoyi-portal\n              predicates:\n                - Path=/oa/dashboard/**,/oa/ai/**\n              filters:\n                - StripPrefix=1\n            # OA 办公自动化（兜底路由，兼容历史路径）\n            - id: ruoyi-oa\n              uri: lb://ruoyi-oa\n              predicates:\n                - Path=/oa/**\n              filters:\n                - StripPrefix=1\n\n            - id: ruoyi-system\n              uri: lb://ruoyi-system\n              predicates:\n                - Path=/system/**\n              filters:\n                - StripPrefix=1\n            # 文件服务\n            - id: ruoyi-file\n              uri: lb://ruoyi-file\n              predicates:\n                - Path=/file/**\n              filters:\n                - StripPrefix=1\n\n# 安全配置\nsecurity:\n  # 验证码\n  captcha:\n    enabled: false\n    type: math\n  # 防止XSS攻击\n  xss:\n    enabled: true\n    excludeUrls:\n      - /system/notice\n\n  # 不校验白名单\n  ignore:\n    whites:\n      - /auth/logout\n      - /auth/login\n      - /auth/register\n      - /code\n      - /*/v2/api-docs\n      - /*/v3/api-docs\n      - /csrf\n\n# springdoc配置\nspringdoc:\n  webjars:\n    # 访问前缀\n    prefix:\n', gmt_modified = NOW() WHERE data_id = 'ruoyi-gateway-dev.yml' AND group_id = 'DEFAULT_GROUP';

INSERT INTO config_info(data_id, group_id, content, md5, gmt_create, gmt_modified, src_user, src_ip, app_name, tenant_id, c_desc, c_use, type, c_schema, encrypted_data_key) VALUES ('ruoyi-approval-dev.yml', 'DEFAULT_GROUP', '# spring配置\nspring:\n  data:\n    redis:\n      host: localhost\n      port: 6379\n      password: \n  datasource:\n    druid:\n      stat-view-servlet:\n        enabled: true\n        loginUsername: ruoyi\n        loginPassword: 123456\n    dynamic:\n      druid:\n        initial-size: 5\n        min-idle: 5\n        maxActive: 20\n        maxWait: 60000\n        connectTimeout: 30000\n        socketTimeout: 60000\n        timeBetweenEvictionRunsMillis: 60000\n        minEvictableIdleTimeMillis: 300000\n        validationQuery: SELECT 1 FROM DUAL\n        testWhileIdle: true\n        testOnBorrow: false\n        testOnReturn: false\n        poolPreparedStatements: true\n        maxPoolPreparedStatementPerConnectionSize: 20\n        filters: stat,slf4j\n        connectionProperties: druid.stat.mergeSql\\=true;druid.stat.slowSqlMillis\\=5000\n      datasource:\n          # 主库数据源\n          master:\n            driver-class-name: com.mysql.cj.jdbc.Driver\n            url: jdbc:mysql://localhost:3306/ry-cloud?useUnicode=true&characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=true&serverTimezone=GMT%2B8\n            username: root\n            password: \n\n# mybatis配置\nmybatis:\n    # 搜索指定包别名\n    typeAliasesPackage: com.ruoyi.oa.approval\n    # 配置mapper的扫描，找到所有的mapper.xml映射文件\n    mapperLocations: classpath:mapper/**/*.xml\n\n# springdoc配置\nspringdoc:\n  gatewayUrl: http://localhost:8000/${spring.application.name}\n  api-docs:\n    # 是否开启接口文档\n    enabled: true\n  info:\n    # 标题\n    title: ''审批服务接口文档''\n    # 描述\n    description: ''审批服务接口描述''\n    # 作者信息\n    contact:\n      name: OA Demo\n      url: https://ruoyi.vip', MD5('# spring配置\nspring:\n  data:\n    redis:\n      host: localhost\n      port: 6379\n      password: \n  datasource:\n    druid:\n      stat-view-servlet:\n        enabled: true\n        loginUsername: ruoyi\n        loginPassword: 123456\n    dynamic:\n      druid:\n        initial-size: 5\n        min-idle: 5\n        maxActive: 20\n        maxWait: 60000\n        connectTimeout: 30000\n        socketTimeout: 60000\n        timeBetweenEvictionRunsMillis: 60000\n        minEvictableIdleTimeMillis: 300000\n        validationQuery: SELECT 1 FROM DUAL\n        testWhileIdle: true\n        testOnBorrow: false\n        testOnReturn: false\n        poolPreparedStatements: true\n        maxPoolPreparedStatementPerConnectionSize: 20\n        filters: stat,slf4j\n        connectionProperties: druid.stat.mergeSql\\=true;druid.stat.slowSqlMillis\\=5000\n      datasource:\n          # 主库数据源\n          master:\n            driver-class-name: com.mysql.cj.jdbc.Driver\n            url: jdbc:mysql://localhost:3306/ry-cloud?useUnicode=true&characterEncoding=utf8&zeroDateTimeBehavior=convertToNull&useSSL=true&serverTimezone=GMT%2B8\n            username: root\n            password: \n\n# mybatis配置\nmybatis:\n    # 搜索指定包别名\n    typeAliasesPackage: com.ruoyi.oa.approval\n    # 配置mapper的扫描，找到所有的mapper.xml映射文件\n    mapperLocations: classpath:mapper/**/*.xml\n\n# springdoc配置\nspringdoc:\n  gatewayUrl: http://localhost:8000/${spring.application.name}\n  api-docs:\n    # 是否开启接口文档\n    enabled: true\n  info:\n    # 标题\n    title: ''审批服务接口文档''\n    # 描述\n    description: ''审批服务接口描述''\n    # 作者信息\n    contact:\n      name: OA Demo\n      url: https://ruoyi.vip'), NOW(), NOW(), 'nacos', '127.0.0.1', '', '', 'OAruoyi-approval', NULL, 'yaml', NULL, '') ON DUPLICATE KEY UPDATE content = VALUES(content), md5 = VALUES(md5), gmt_modified = NOW();

